package com.yeyamo_mobile.api.culture_service.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.yeyamo_mobile.api.culture_service.domain.*;import com.yeyamo_mobile.api.culture_service.infrastructure.persistence.ChallengeRepositories.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class)class CultureChallengeServiceTest{@Mock Challenges challenges;@Mock Prompts prompts;@Mock Participants participants;@Mock Submissions submissions;@Mock Consents consents;@Mock CultureEventPublisher events;CultureChallengeService service;@BeforeEach void setUp(){service=new CultureChallengeService(challenges,prompts,participants,submissions,consents,events);}@Test void rejectsExpiredChallenge(){UUID id=UUID.randomUUID();CultureChallenge challenge=mock(CultureChallenge.class);when(challenges.findById(id)).thenReturn(Optional.of(challenge));when(challenge.available(any(Instant.class))).thenReturn(false);assertEquals("CHALLENGE_NOT_ACTIVE",assertThrows(CultureException.class,()->service.join(id,"user")).getCode());}@Test void doubleJoinIsIdempotent(){UUID id=UUID.randomUUID();CultureChallenge challenge=mock(CultureChallenge.class);CultureChallengeParticipant participant=CultureChallengeParticipant.join(id,"user");when(challenges.findById(id)).thenReturn(Optional.of(challenge));when(challenge.available(any(Instant.class))).thenReturn(true);when(participants.findByChallengeIdAndUserId(id,"user")).thenReturn(Optional.of(participant));service.join(id,"user");service.join(id,"user");verify(participants,never()).save(any());verify(events,never()).publish(eq("CultureChallengeJoined"),any(),any());}@Test void requiresConsentForRecordedPerson(){UUID id=UUID.randomUUID();CultureChallenge challenge=mock(CultureChallenge.class);when(challenges.findById(id)).thenReturn(Optional.of(challenge));when(challenge.available(any(Instant.class))).thenReturn(true);when(participants.findByChallengeIdAndUserId(id,"user")).thenReturn(Optional.of(CultureChallengeParticipant.join(id,"user")));ChallengeDtos.SubmissionRequest request=new ChallengeDtos.SubmissionRequest(null,null,List.of(UUID.randomUUID()),"fr-CM",null,true,false,true,null,false,false,false,false);assertEquals("CONSENT_REQUIRED",assertThrows(CultureException.class,()->service.submit(id,request,"user")).getCode());}}
